const input = $input.item.json;
const isError = input.error !== undefined;
const timestamp = new Date().toISOString();

const splitData = $('SPLIT URLs').item.json;
const url = splitData.url || 'Unknown';
const name = splitData.name || splitData['website name'] || 'Unknown';

// Accurate response time
const responseTime = isError ? 0 : (
  input.headers?.['x-response-time']
    ? parseInt(input.headers['x-response-time'])
    : input.headers?.['x-runtime']
      ? Math.round(parseFloat(input.headers['x-runtime']) * 1000)
      : 999
);

let statusCode, status, note, errorType;

if (isError) {
  statusCode = 0;
  const errMsg = input.error?.message || input.error?.code || 'No response';

  if (errMsg.includes('CERT') || errMsg.includes('SSL') || errMsg.includes('certificate')) {
    status = "DOWN"; note = `SSL Error - ${errMsg}`; errorType = "SSL";
  } else if (errMsg.includes('ENOTFOUND') || errMsg.includes('DNS')) {
    status = "DOWN"; note = `DNS Failed - Domain not found`; errorType = "DNS";
  } else if (errMsg.includes('ECONNREFUSED')) {
    status = "DOWN"; note = `Connection Refused`; errorType = "CONNECTION";
  } else if (errMsg.includes('ETIMEDOUT') || errMsg.includes('timeout')) {
    status = "DOWN"; note = `Timeout - Server not responding`; errorType = "TIMEOUT";
    } else if (errMsg.includes('ECONNRESET')) {
  status = "DOWN"; 
  note = `Connection Reset - Server closed connection unexpectedly`; 
  errorType = "CONNECTION_RESET";
  } else {
    status = "DOWN"; note = `Unreachable - ${errMsg}`; errorType = "UNKNOWN";
  }
} else {
  statusCode = input.statusCode || 200;

  if (statusCode >= 500) {
    status = "DOWN"; note = `Server Error - ${statusCode}`; errorType = "SERVER_ERROR";
  } else if (statusCode === 404) {
    status = "DOWN"; note = `Not Found - 404`; errorType = "NOT_FOUND";
  } else if (statusCode === 403) {
    status = "DOWN"; note = `Forbidden - 403`; errorType = "FORBIDDEN";
  } else if (statusCode >= 400) {
    status = "DOWN"; note = `Client Error - ${statusCode}`; errorType = "CLIENT_ERROR";
  } else if (responseTime > 5000) {
    status = "DOWN"; note = `Critical Slow - ${responseTime}ms`; errorType = "CRITICAL_SLOW";
  } else if (responseTime > 3000) {
    status = "SLOW"; note = `Slow - ${responseTime}ms`; errorType = "SLOW";
  } else if (responseTime > 1500) {
    status = "SLOW"; note = `Moderate Slow - ${responseTime}ms`; errorType = "MODERATE_SLOW";
  } else {
    status = "UP"; note = `All good - ${responseTime}ms`; errorType = "NONE";
  }
}

return {
  json: { url, name, status, statusCode, responseTime, note, timestamp, errorType }
};

