const aiResponse = $input.item.json.output 
  || $input.item.json.text 
  || $input.item.json.content
  || $input.item.json.message;

const clean = aiResponse
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const report = JSON.parse(clean);
return { json: report };

const report = $input.item.json;

// HTML string তৈরি করো (পুরো template)
const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; background: #f4f4f4; margin: 0; padding: 20px; }
  .container { max-width: 650px; margin: auto; background: #fff; border-radius: 8px; overflow: hidden; }
  .header { background: #1565C0; padding: 28px 32px; }
  .header h1 { color: #fff; margin: 0; font-size: 22px; }
  .header p { color: #bbdefb; margin: 6px 0 0; font-size: 14px; }
  .body { padding: 32px; }
  .summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 32px; }
  .summary-card { background: #f5f5f5; border-radius: 6px; padding: 16px; text-align: center; }
  .summary-card .number { font-size: 28px; font-weight: bold; color: #1565C0; }
  .summary-card .label { font-size: 12px; color: #888; margin-top: 4px; }
  .section-title { font-size: 13px; font-weight: 700; color: #888; text-transform: uppercase; letter-spacing: 1px; margin: 28px 0 12px; border-bottom: 1px solid #eee; padding-bottom: 8px; }
  .site-card { border: 1px solid #eee; border-radius: 6px; padding: 16px; margin-bottom: 12px; }
  .site-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
  .site-name { font-weight: bold; font-size: 15px; color: #222; }
  .badge { padding: 3px 10px; border-radius: 12px; font-size: 12px; font-weight: bold; }
  .badge-critical { background: #ffebee; color: #c62828; }
  .badge-warning { background: #fff8e1; color: #f57f17; }
  .badge-healthy { background: #e8f5e9; color: #2e7d32; }
  .site-url { font-size: 12px; color: #999; margin-bottom: 10px; }
  .site-detail { font-size: 13px; color: #555; margin: 4px 0; }
  .site-rec { font-size: 13px; color: #1565C0; margin-top: 8px; font-style: italic; }
  .solution-box { background: #e3f2fd; border-left: 3px solid #1565C0; border-radius: 4px; padding: 10px 12px; margin-top: 10px; font-size: 13px; color: #0d47a1; }
  .incident-section { margin-top: 12px; border-top: 1px solid #eee; padding-top: 10px; }
  .incident-label { font-size: 12px; font-weight: 700; color: #888; margin-bottom: 6px; }
  .incident-item { background: #f9f9f9; border-left: 3px solid #ef9a9a; border-radius: 4px; padding: 8px 10px; margin-bottom: 6px; font-size: 12px; color: #444; line-height: 1.8; }
  .incident-item.recovered { border-left-color: #a5d6a7; }
  .issue-list { list-style: none; padding: 0; margin: 0; }
  .issue-list li { padding: 8px 12px; border-radius: 4px; margin-bottom: 6px; font-size: 13px; }
  .issue-critical { background: #ffebee; color: #c62828; }
  .issue-minor { background: #fff8e1; color: #f57f17; }
  .issue-healthy { background: #e8f5e9; color: #2e7d32; }
  .action-card { border: 1px solid #eee; border-radius: 6px; padding: 14px 16px; margin-bottom: 10px; }
  .footer { background: #f9f9f9; padding: 16px 32px; font-size: 12px; color: #aaa; border-top: 1px solid #eee; text-align: center; }
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <h1>📊 Weekly Website Monitor Report</h1>
    <p>Period: ${report.summary.reportPeriod}</p>
  </div>
  <div class="body">

    <div class="summary-grid">
      <div class="summary-card"><div class="number">${report.summary.totalChecks}</div><div class="label">Total Checks</div></div>
      <div class="summary-card"><div class="number">${report.summary.totalIncidents}</div><div class="label">Total Incidents</div></div>
      <div class="summary-card"><div class="number">${report.websites.length}</div><div class="label">Sites Monitored</div></div>
    </div>

    <div class="section-title">🚨 Immediate Actions Required</div>
    ${report.immediateActions && report.immediateActions.length > 0
      ? report.immediateActions.map(action => `
        <div class="action-card">
          <div class="site-header">
            <span class="site-name">🌐 ${action.website}</span>
            <span class="badge badge-${action.priority === 'High' ? 'critical' : action.priority === 'Medium' ? 'warning' : 'healthy'}">${action.priority} Priority</span>
          </div>
          <div class="site-detail">✅ <strong>Action:</strong> ${action.action}</div>
          <div class="site-detail">📌 <strong>Reason:</strong> ${action.reason}</div>
        </div>
      `).join('')
      : '<p style="font-size:13px;color:#2e7d32;">✅ No immediate actions required.</p>'
    }

    <div class="section-title">Website Status Breakdown</div>
    ${report.websites.map(site => `
      <div class="site-card">
        <div class="site-header">
          <span class="site-name">${site.name}</span>
          <span class="badge badge-${site.severity.toLowerCase()}">${site.severity}</span>
        </div>
        <div class="site-url">${site.url}</div>
        <div class="site-detail">📉 Incidents: <strong>${site.totalIncidents}</strong></div>
        <div class="site-detail">🔍 Most Common Error: <strong>${site.mostCommonError}</strong></div>
        <div class="site-detail">⏱ Uptime: <strong>${site.uptimePercent}%</strong></div>
        <div class="site-rec">💡 ${site.recommendation}</div>
        ${site.solution ? `<div class="solution-box">🔧 <strong>How to Fix:</strong> ${site.solution}</div>` : ''}
        ${site.incidents && site.incidents.length > 0 ? `
          <div class="incident-section">
            <div class="incident-label">INCIDENT HISTORY</div>
            ${site.incidents.map(inc => `
              <div class="incident-item ${inc.recovery === 'Auto Recovered' ? 'recovered' : ''}">
                🔴 <strong>Down At:</strong> ${inc.downAt}<br>
                ⚠️ <strong>Reason:</strong> ${inc.reason}<br>
                🔍 <strong>Error Type:</strong> ${inc.errorType}<br>
                🔧 <strong>Fix:</strong> ${inc.solution || 'See site recommendation above'}<br>
                ✅ <strong>Recovered At:</strong> ${inc.upAt}<br>
                ⏱ <strong>Duration:</strong> ${inc.duration}<br>
                🔄 <strong>Status:</strong> ${inc.recovery}
              </div>
            `).join('')}
          </div>
        ` : ''}
      </div>
    `).join('')}

    <div class="section-title">🔴 Critical Issues</div>
    <ul class="issue-list">
      ${report.criticalIssues.length > 0
        ? report.criticalIssues.map(i => `<li class="issue-critical">⚠️ ${i}</li>`).join('')
        : '<li class="issue-healthy">✅ No critical issues this week</li>'}
    </ul>

    <div class="section-title">🟡 Minor Issues</div>
    <ul class="issue-list">
      ${report.minorIssues.length > 0
        ? report.minorIssues.map(i => `<li class="issue-minor">• ${i}</li>`).join('')
        : '<li class="issue-healthy">✅ No minor issues this week</li>'}
    </ul>

    <div class="section-title">✅ Healthy Websites</div>
    <ul class="issue-list">
      ${report.healthyWebsites.length > 0
        ? report.healthyWebsites.map(i => `<li class="issue-healthy">✅ ${i}</li>`).join('')
        : '<li class="issue-minor">• No fully healthy websites this week</li>'}
    </ul>

  </div>
  <div class="footer">Automated Weekly Report — Website Monitor System</div>
</div>
</body>
</html>`;

return {
  json: {
    ...report,
    htmlReport: html
  }
};

const aggregated = $input.item.json;

// AGGREGATE এর পরে data array বের করো
const allRows = Array.isArray(aggregated) 
  ? aggregated 
  : Object.values(aggregated).find(v => Array.isArray(v)) || [];

const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const thisWeekRows = allRows.filter(row => {
  const ts = new Date(row.TIMESTAMP || row.timestamp);
  return ts >= oneWeekAgo;
});

return {
  json: {
    data: thisWeekRows,
    weekStart: oneWeekAgo.toISOString(),
    weekEnd: now.toISOString()
  }
};
